// Babel Matrix - neural bandwidth demo (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var bw=[0.5,120,20000];
console.log("Babel Matrix - what the bandwidth carries");
console.log("==================================================");
var loads=[["text thought",0.01],["speech",0.1],["full sensory",50],["memory share",500]];
for(var m=0;m<3;m++){
  console.log("Mark "+(m+1)+": "+bw[m]+" Mbps");
  for(var i=0;i<loads.length;i++){ var ok=bw[m]>=loads[i][1]?"yes":"no"; console.log("  "+loads[i][0]+" ("+loads[i][1]+" Mbps): "+ok); }
}
console.log("Mental privacy: all sessions encrypted, user-terminable instantly.");

